// A scripted stand-in for the desktop shell, used by `npm run dev:mock`,
// by tests, and whenever the UI runs outside Tauri. It implements the same
// commands and events; the meeting itself is a replay of a session recorded
// from the real pipeline (sdn-demo.json, regenerated by the record_demo
// example), so what you see here is what the pipeline actually emits.

import type { AppEvent } from "../bindings/AppEvent";
import type { MeetCueEvent } from "../bindings/MeetCueEvent";
import type { PointStatus } from "../bindings/PointStatus";
import type { PriceEntry } from "../bindings/PriceEntry";
import type { PriceTable } from "../bindings/PriceTable";
import type { ProbeReport } from "../bindings/ProbeReport";
import type { Settings } from "../bindings/Settings";
import type { TimedEvent } from "../bindings/TimedEvent";
import type { UserAction } from "../bindings/UserAction";
import type { PracticeScript } from "../bindings/PracticeScript";
import type { PracticeReport } from "../bindings/PracticeReport";
import pricing from "../../../../crates/core/data/pricing.json";
import { emptySession, reduce, type SessionView } from "../state/session";
import type { Backend, CommandName, Commands } from "../backend/types";
import type { LogLine } from "../bindings/LogLine";
import { estimateHourly } from "../util/cost";
import defaults from "./default-settings.json";
import demo from "./sdn-demo.json";
import { mockPracticeReport, mockPracticeScript } from "./practice";

type Listener<T> = (e: T) => void;

const HOSTS: Record<string, string[]> = {
  soniox: ["stt-rt.soniox.com", "stt-rt.eu.soniox.com", "stt-rt.jp.soniox.com", "stt-rt.in.soniox.com"],
  deepgram: ["api.deepgram.com", "api.eu.deepgram.com", "api.au.deepgram.com", "api.in.deepgram.com"],
  anthropic: ["api.anthropic.com"],
  "openai-compatible": [],
};


export function createMockBackend(options: { speed?: number } = {}): Backend {
  const speed = options.speed ?? 1;
  const events = new Set<Listener<MeetCueEvent>>();
  const appEvents = new Set<Listener<AppEvent>>();
  let settings: Settings = structuredClone(defaults) as unknown as Settings;
  const credentials = new Map<string, string>();
  let history: TimedEvent[] = [];
  let view: SessionView = emptySession();
  let timers: number[] = [];
  let startWall = 0;
  let state: "idle" | "running" | "paused" | "stopped" = "idle";
  let pausedAt = 0;
  let replayIndex = 0;
  const probes: ProbeReport[] = [];
  let practiceScript: PracticeScript | null = null;
  let previewTimer = 0;
  let prices = structuredClone(pricing) as PriceTable;

  // Activity log in the same shape as the desktop shell's log lines.
  const logs: LogLine[] = [];
  const log = (level: "INFO" | "WARN", target: string, message: string) => {
    logs.push({ seq: (logs[logs.length - 1]?.seq ?? 0) + 1, line: `${new Date().toISOString()}  ${level.padStart(5)} ${target}: ${message}` });
    if (logs.length > 1000) logs.shift();
  };
  log("INFO", "meetcue", "MeetCue preview starting (scripted backend)");
  const logEvent = (e: MeetCueEvent) => {
    const target = "meetcue::session";
    if (e.type === "sessionState") log("INFO", target, `session ${e.state}`);
    if (e.type === "transcript" && e.isFinal) log("INFO", target, `recognised a sentence from ${e.channel} (${[...e.text].length} characters)`);
    if (e.type === "questionNew") log("INFO", target, `question ${e.id} detected (version ${e.version})`);
    if (e.type === "answerDone") log("INFO", target, `hints for question ${e.id} ready`);
    if (e.type === "error") log("WARN", target, `code=${e.code} ${e.detail}`);
  };

  const emit = (e: MeetCueEvent) => {
    logEvent(e);
    view = reduce(view, e);
    if (!(e.type === "transcript" && !e.isFinal) && e.type !== "levels") {
      history.push({ tMs: Date.now() - startWall, event: e });
    }
    for (const l of events) l(e);
  };
  const emitApp = (e: AppEvent) => {
    for (const l of appEvents) l(e);
  };

  const script = demo as TimedEvent[];

  // Practice preview: walks through the questions on a timer.
  let practiceIndex = 0;
  let practiceTimer = 0;
  const practiceTotal = () => practiceScript?.items.filter((i) => !i.isMe).length ?? 0;
  const emitPractice = (phase: string) =>
    emitApp({
      type: "practiceProgress",
      index: Math.min(practiceIndex, practiceTotal()),
      total: practiceTotal(),
      phase,
      question: practiceScript?.items[practiceIndex - 1]?.text ?? "",
    });
  const finishPractice = () => {
    window.clearTimeout(practiceTimer);
    clearTimers();
    state = "stopped";
    emit({ type: "sessionState", state: "stopped", tMs: Date.now() - startWall });
    emitApp({ type: "practiceProgress", index: 0, total: 0, phase: "done", question: "" });
    emitApp({ type: "practiceFinished", reportId: "demo" });
  };
  const practiceStep = () => {
    window.clearTimeout(practiceTimer);
    practiceIndex++;
    if (practiceIndex > practiceTotal()) {
      finishPractice();
      return;
    }
    emitPractice("speaking");
    practiceTimer = window.setTimeout(() => {
      emitPractice("waiting");
      practiceTimer = window.setTimeout(() => {
        emitPractice("answering");
        practiceTimer = window.setTimeout(practiceStep, 14_000 / speed);
      }, 2_000 / speed);
    }, 3_000 / speed);
  };

  const schedule = () => {
    const base = Date.now() - (script[replayIndex]?.tMs ?? 0) / speed;
    for (let i = replayIndex; i < script.length; i++) {
      const item = script[i];
      const delay = Math.max(0, base + item.tMs / speed - Date.now());
      timers.push(
        window.setTimeout(() => {
          replayIndex = i + 1;
          const e = item.event;
          if (e.type === "sessionState" && e.state !== "running") return;
          emit(e);
          if (e.type === "transcript") {
            const level = e.isFinal ? -60 : -22 - Math.random() * 10;
            emit({ type: "levels", me: e.channel === "me" ? level : -70, remote: e.channel === "remote" ? level : -70 });
          }
        }, delay),
      );
    }
  };

  const clearTimers = () => {
    for (const t of timers) window.clearTimeout(t);
    timers = [];
  };

  const toggle = () => {
    if (state === "idle" || state === "stopped") {
      clearTimers();
      history = [];
      view = emptySession();
      replayIndex = 0;
      startWall = Date.now();
      state = "running";
      emit({ type: "sessionState", state: "running", tMs: 0 });
      replayIndex = 1;
      schedule();
    } else if (state === "running") {
      state = "paused";
      pausedAt = Date.now();
      clearTimers();
      emit({ type: "sessionState", state: "paused", tMs: Date.now() - startWall });
    } else {
      state = "running";
      startWall += Date.now() - pausedAt;
      emit({ type: "sessionState", state: "running", tMs: Date.now() - startWall });
      schedule();
    }
  };

  const action = (a: UserAction) => {
    const queue = () => {
      emit({
        type: "queueChanged",
        questions: view.order.map((id) => ({ id, short: view.questions[id].short, status: view.questions[id].status })),
        active: view.active,
        focus: view.focus,
      });
    };
    switch (a.type) {
      case "focus":
        view = { ...view, focus: a.id };
        queue();
        break;
      case "focusStep": {
        const cur = view.focus ?? view.active ?? view.order[view.order.length - 1];
        const i = view.order.indexOf(cur ?? -1) + (a.target === "next" ? 1 : -1);
        if (i >= 0 && i < view.order.length) {
          view = { ...view, focus: view.order[i] };
          queue();
        }
        break;
      }
      case "markAnswered":
        if (view.active !== null) {
          emit({ type: "questionStatus", id: view.active, status: "answered" });
          const next = view.order.find((id) => view.questions[id].status === "pending") ?? null;
          if (next !== null) emit({ type: "questionStatus", id: next, status: "active" });
          view = { ...view, active: next, focus: null };
          queue();
        }
        break;
      case "togglePoint": {
        const points = view.questions[a.id]?.points ?? [];
        if (!points[a.index]) break;
        const done = points.map((p, i) => (i === a.index ? p.status !== "done" : p.status === "done"));
        const next = done.indexOf(false);
        const statuses = done.map((d, i) => (d ? "done" : i === next ? "next" : "todo") as PointStatus);
        emit({ type: "coverage", id: a.id, statuses });
        break;
      }
      case "pause":
      case "resume":
        toggle();
        break;
    }
  };

  const handlers: { [K in CommandName]: (args: Commands[K]["args"]) => Promise<Commands[K]["result"]> | Commands[K]["result"] } = {
    get_app_info: () => ({
      version: "0.1.0",
      platform: "web",
      language: settings.general.uiLanguage === "system" ? (navigator.language.startsWith("zh") ? "zh-CN" : "en") : settings.general.uiLanguage,
      systemLocale: navigator.language,
      portable: false,
      configDir: "(browser preview)",
      demo: true,
      docsUrl: "https://amazingkenneth.github.io/meetcue/",
      captureSupported: false,
    }),
    get_settings: () => structuredClone(settings),
    save_settings: ({ settings: s }) => {
      settings = structuredClone(s);
      emitApp({ type: "settingsChanged", settings: structuredClone(s) });
      return structuredClone(s);
    },
    list_devices: () => ({
      microphones: [
        { id: "mic-1", name: "Microphone Array (Realtek(R) Audio)", isDefault: true, isBluetooth: false },
        { id: "mic-2", name: "Headset (WH-1000XM4 Hands-Free AG Audio)", isDefault: false, isBluetooth: true },
      ],
      outputs: [{ id: "out-1", name: "Speakers (Realtek(R) Audio)", isDefault: true, isBluetooth: false }],
    }),
    credential_status: () => Object.fromEntries([...credentials.keys()].map((k) => [k, true])),
    set_credential: ({ key, value }) => {
      credentials.set(key, value);
      return null;
    },
    delete_credential: ({ key }) => {
      credentials.delete(key);
      return null;
    },
    verify_provider: ({ provider }) =>
      credentials.has(provider) || provider === "openai-compatible"
        ? { ok: true, code: null, detail: null }
        : { ok: false, code: provider === "soniox" || provider === "deepgram" ? "MC-ASR-001" : "MC-LLM-002", detail: "no key" },
    list_models: ({ provider }) => [
      ...(pricing.entries as PriceEntry[])
        .filter((e) => e.provider === provider)
        .map((e) => ({ id: e.model, displayName: e.label || e.model })),
      // Providers also list models the price list doesn't cover.
      ...(provider === "anthropic" ? [{ id: "claude-opus-4-8", displayName: "Claude Opus 4.8" }] : []),
    ],
    get_pricing: () => prices,
    refresh_pricing: () => {
      // Like the shell, add the prices read live from the providers' pages.
      const live: PriceEntry = {
        provider: "anthropic",
        model: "claude-opus-4-8",
        label: "Claude Opus 4.8",
        unit: "per_million_tokens",
        input: 5,
        output: 25,
        cacheRead: 0.5,
        cacheWrite: 6.25,
        source: "https://platform.claude.com/docs/en/about-claude/pricing",
        verified: new Date().toISOString().slice(0, 10),
      };
      prices = { ...prices, updated: live.verified, entries: [...prices.entries.filter((e) => e.model !== live.model), live] };
      emitApp({ type: "pricingChanged", pricing: prices });
      return prices;
    },
    estimate_cost: ({ asr, detect, hints, assumptions }) => estimateHourly(asr, detect, hints, assumptions),
    provider_hosts: ({ provider }) => HOSTS[provider] ?? [],
    audio_preview: ({ on }) => {
      if (previewTimer) window.clearInterval(previewTimer);
      previewTimer = 0;
      if (on) {
        previewTimer = window.setInterval(
          () => emit({ type: "levels", me: -30 - Math.random() * 25, remote: -25 - Math.random() * 30 }),
          150,
        );
      }
      return null;
    },
    start_session: () => {
      if (state !== "running") toggle();
      return null;
    },
    stop_session: () => {
      clearTimers();
      state = "stopped";
      emit({ type: "sessionState", state: "stopped", tMs: Date.now() - startWall });
      return null;
    },
    toggle_capture: () => {
      toggle();
      return null;
    },
    user_action: ({ action: a }) => {
      action(a);
      return null;
    },
    session_history: () => [...history],
    recent_logs: ({ after }) => logs.filter((l) => l.seq > after),
    set_panel_mode: ({ mode }) => {
      settings = { ...settings, overlay: { ...settings.overlay, mode } };
      emitApp({ type: "panelMode", mode });
      emitApp({ type: "settingsChanged", settings });
      return null;
    },
    set_always_on_top: () => null,
    reset_panel_position: () => null,
    open_window: ({ view: v, section }) => {
      window.open(`?view=${v}${section ? `#${section}` : ""}`, "_blank");
      return null;
    },
    open_url: ({ url }) => {
      window.open(url, "_blank", "noopener");
      return null;
    },
    hotkey_status: () =>
      Object.entries(settings.hotkeys).map(([action, accelerator]) => ({ action, accelerator: accelerator as string, ok: true })),
    run_probe: async ({ request }) => {
      const total = request.targets.length;
      for (let i = 0; i < total; i++) {
        emitApp({ type: "probeProgress", done: i, total, label: request.targets[i].provider });
        await new Promise((r) => setTimeout(r, 250));
      }
      emitApp({ type: "probeProgress", done: total, total, label: "" });
      const report = mockProbe(request.networkOnly, request.label ?? null);
      probes.unshift(report);
      return report;
    },
    probe_history: () => probes,
    usage_summary: () => ({
      month: new Date().toISOString().slice(0, 7),
      rows: [
        { provider: "soniox", model: "stt-rt-v5", calls: 4, inputTokens: 0, outputTokens: 0, audioMs: 5_400_000, micros: 180_000 },
        { provider: "anthropic", model: "claude-haiku-5-5", calls: 61, inputTokens: 118_000, outputTokens: 21_500, audioMs: 0, micros: 22_550 },
      ],
      totalMicros: 202_550,
    }),
    export_usage_csv: () => "usage.csv",
    diagnostics_preview: () => [
      "logs/meetcue.2026-10-22.log",
      "settings.json (API keys are never stored here)",
      "latency-history.json",
      "system.txt (OS version, audio devices, sample rates)",
    ],
    export_diagnostics: () => "meetcue-diagnostics.zip",
    import_material: () => ({ name: "agenda.md", path: "agenda.md", text: "Agenda: network architecture review, SDN rollout, failover drills." }),
    practice_import: () => {
      practiceScript = mockPracticeScript();
      return practiceScript;
    },
    list_voices: () => [
      { id: "mock-en", name: "Microsoft Aria (English)", lang: "en" },
      { id: "mock-zh", name: "Microsoft Xiaoxiao (Chinese)", lang: "zh" },
    ],
    preview_voice: () => null,
    practice_sample: ({ name }) => {
      practiceScript = { ...mockPracticeScript(), title: name.replace(/\.[^.]+$/, "") };
      return practiceScript;
    },
    practice_classify: ({ script }) => ({
      ...script,
      needsClassification: false,
      items: script.items.map((it) => ({ ...it, isQuestion: /[?？]$/.test(it.text), isMe: !/[?？]$/.test(it.text) })),
    }),
    practice_start: ({ script }) => {
      practiceScript = script;
      practiceIndex = 0;
      if (state !== "running") toggle();
      practiceStep();
      return null;
    },
    practice_control: ({ control }) => {
      if (control === "stop") {
        finishPractice();
      } else if (control === "pause" || control === "resume") {
        toggle();
        emitPractice(state === "paused" ? "paused" : "answering");
      } else if (control === "skip" || control === "answered") {
        practiceStep();
      }
      return null;
    },
    practice_reports: () => [
      { id: "demo", title: "Network architecture", startedAt: new Date().toISOString(), questions: 3, avgStartLatencyMs: 1800, avgCoverage: 0.83 },
    ],
    practice_report: (): PracticeReport => mockPracticeReport(),
    export_report: () => "practice-report.md",
  };

  return {
    kind: "mock",
    async invoke<K extends CommandName>(cmd: K, ...args: unknown[]) {
      const handler = handlers[cmd] as (a: unknown) => Promise<Commands[K]["result"]> | Commands[K]["result"];
      return handler(args[0]);
    },
    async onEvent(cb) {
      events.add(cb);
      return () => events.delete(cb);
    },
    async onAppEvent(cb) {
      appEvents.add(cb);
      return () => appEvents.delete(cb);
    },
    async closeWindow() {
      window.close();
    },
  };
}

function mockProbe(networkOnly: boolean, label: string | null): ProbeReport {
  const stat = (m: number) => ({ medianMs: m, maxMs: Math.round(m * 1.4), samples: 5 });
  const asr = [
    { host: "stt-rt.soniox.com", net: 38, fin: 310, part: 240 },
    { host: "stt-rt.eu.soniox.com", net: 162, fin: 520, part: 410 },
    { host: "stt-rt.jp.soniox.com", net: 95, fin: 390, part: 300 },
  ];
  return {
    at: new Date().toISOString(),
    label,
    networkOnly,
    results: [
      ...asr.map((a) => ({
        provider: "soniox",
        kind: "asr",
        host: a.host,
        model: "stt-rt-v5",
        dns: stat(8),
        tcp: stat(a.net),
        tls: stat(a.net * 2),
        firstPartial: networkOnly ? null : stat(a.part),
        finalResult: networkOnly ? null : stat(a.fin),
        firstToken: null,
        firstPoint: null,
        error: null,
        hourlyMicros: 144_000,
      })),
      {
        provider: "anthropic",
        kind: "llm",
        host: "api.anthropic.com",
        model: "claude-haiku-5-5",
        dns: stat(6),
        tcp: stat(45),
        tls: stat(92),
        firstPartial: null,
        finalResult: null,
        firstToken: networkOnly ? null : stat(330),
        firstPoint: networkOnly ? null : stat(520),
        error: null,
        hourlyMicros: 11_000,
      },
    ],
    combos: networkOnly
      ? []
      : asr.map((a) => ({
          asrProvider: "soniox",
          asrHost: a.host,
          asrModel: "stt-rt-v5",
          llmProvider: "anthropic",
          llmHost: "api.anthropic.com",
          llmModel: "claude-haiku-5-5",
          endToEndMs: 400 + a.fin + 330 + 520,
          hourlyMicros: 155_000,
        })),
  };
}
